/*
 * A348715  Numbers whose divisors can be partitioned into two disjoint sets
 *          without singletons whose harmonic means are both integers.
 * https://oeis.org/A348715
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th integer whose set of divisors can be partitioned
 *            into two disjoint non‑singleton subsets whose harmonic means are
 *            both integers. The sequence is generated by a search
 * Range:     u8 n <= 2, u16 n <= 24, u32 n <= 56, u64 n <= 56, u128 n <= 56,
 *            big any n
 * Helpers:   seq_gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include <math.h>
#include "../utils/seq_gcd.h"

/* ---------- Prime utilities ---------- */
static uint32_t *g_primes = NULL;      /* list of primes */
static size_t   g_prime_count = 0;
static size_t   g_prime_cap   = 0;
static uint32_t g_prime_limit = 1;     /* primes generated up to this value */

static void ensure_primes(uint32_t limit)
{
    if (limit <= g_prime_limit) return;
    if (g_prime_cap == 0) {
        g_prime_cap = limit + 1;
        g_primes = (uint32_t*)malloc(g_prime_cap * sizeof(uint32_t));
        if (!g_primes) abort();
    } else if (g_prime_cap < limit + 1) {
        g_prime_cap = limit + 1;
        g_primes = (uint32_t*)realloc(g_primes, g_prime_cap * sizeof(uint32_t));
        if (!g_primes) abort();
    }
    for (uint32_t cand = g_prime_limit + 1; cand <= limit; ++cand) {
        bool is_prime = true;
        for (size_t i = 0; i < g_prime_count; ++i) {
            uint32_t p = g_primes[i];
            if ((uint64_t)p * p > cand) break;
            if (cand % p == 0) { is_prime = false; break; }
        }
        if (is_prime) {
            g_primes[g_prime_count++] = cand;
        }
    }
    g_prime_limit = limit;
}

/* ---------- Divisor generation ---------- */
static void gen_divisors_rec(const uint32_t *fac, const int *exp, size_t fac_cnt,
                             uint64_t cur, size_t depth,
                             uint64_t *divs, size_t *div_idx)
{
    if (depth == fac_cnt) {
        divs[(*div_idx)++] = cur;
        return;
    }
    uint64_t mult = 1;
    for (int e = 0; e <= exp[depth]; ++e) {
        gen_divisors_rec(fac, exp, fac_cnt, cur * mult, depth + 1, divs, div_idx);
        mult *= fac[depth];
    }
}

/* ---------- Search helpers ---------- */
struct SearchContext {
    const uint64_t *divs;
    size_t           div_count;
    seq_t            total_num;
    seq_t            total_den;
};

static bool search_subset(const struct SearchContext *ctx, size_t idx, size_t sz,
                          seq_t rec_num, seq_t rec_den)
{
    size_t remaining = ctx->div_count - idx;
    if (sz > ctx->div_count - 2) return false;      /* too many in S */
    if (sz + remaining < 2) return false;           /* cannot reach size 2 */

    if (idx == ctx->div_count) {
        if (sz < 2 || sz > ctx->div_count - 2) return false;
        /* Harmonic mean of S */
        seq_t hs_n = (seq_t)sz;                       /* numerator factor */
        if ( (hs_n * rec_den) % rec_num != 0 ) return false;

        /* Complement subset T */
        seq_t g1  = seq_gcd(ctx->total_den, rec_den);
        seq_t lcm = ctx->total_den / g1 * rec_den;
        seq_t term1 = ctx->total_num * (lcm / ctx->total_den);
        seq_t term2 = rec_num * (lcm / rec_den);
        seq_t comp_num = term1 - term2;
        seq_t comp_den = lcm;
        seq_t g2 = seq_gcd(comp_num, comp_den);
        comp_num /= g2;
        comp_den /= g2;
        size_t sz2 = ctx->div_count - sz;
        if ( ((seq_t)sz2 * comp_den) % comp_num == 0 ) return true;
        return false;
    }

    /* Option 1: exclude current divisor */
    if (search_subset(ctx, idx + 1, sz, rec_num, rec_den)) return true;

    /* Option 2: include current divisor */
    uint64_t d = ctx->divs[idx];
    seq_t new_num = rec_num * (seq_t)d + rec_den;
    seq_t new_den = rec_den * (seq_t)d;
    seq_t g = seq_gcd(new_num, new_den);
    new_num /= g;
    new_den /= g;
    if (search_subset(ctx, idx + 1, sz + 1, new_num, new_den)) return true;
    return false;
}

/* ---------- Core validity test ---------- */
static bool is_valid_number(uint64_t m)
{
    if (m < 12) return false;                     /* first term is 12 */

    /* Build primes up to sqrt(m) if needed */
    uint32_t sqrt_limit = (uint32_t)sqrt((double)m) + 1;
    if (sqrt_limit > g_prime_limit) ensure_primes(sqrt_limit);

    /* Factorization: store in small arrays */
    uint32_t fac[16];
    int      exp[16];
    size_t   fac_cnt = 0;
    uint64_t temp = m;
    for (size_t i = 0; i < g_prime_count && (uint64_t)g_primes[i]*g_primes[i] <= temp; ++i) {
        if (temp % g_primes[i] == 0) {
            int cnt = 0;
            while (temp % g_primes[i] == 0) { temp /= g_primes[i]; ++cnt; }
            fac[fac_cnt] = g_primes[i];
            exp[fac_cnt] = cnt;
            ++fac_cnt;
        }
    }
    if (temp > 1) {
        fac[fac_cnt] = (uint32_t)temp;
        exp[fac_cnt] = 1;
        ++fac_cnt;
    }

    /* Compute total number of divisors to preallocate array */
    size_t total_divs = 1;
    for (size_t i = 0; i < fac_cnt; ++i) total_divs *= (size_t)(exp[i] + 1);

    uint64_t *divs = (uint64_t*)malloc(total_divs * sizeof(uint64_t));
    if (!divs) abort();
    size_t div_idx = 0;
    gen_divisors_rec(fac, exp, fac_cnt, 1ULL, 0, divs, &div_idx);
    size_t div_count = div_idx;

    if (div_count < 4) {                 /* cannot split into two non‑singleton sets */
        free(divs);
        return false;
    }

    /* Sum of reciprocals over all divisors: total_num / total_den */
    seq_t sum_num = 0;
    seq_t sum_den = 1;
    for (size_t i = 0; i < div_count; ++i) {
        uint64_t d = divs[i];
        seq_t new_num = sum_num * (seq_t)d + sum_den;
        seq_t new_den = sum_den * (seq_t)d;
        seq_t g = seq_gcd(new_num, new_den);
        new_num /= g;
        new_den /= g;
        sum_num = new_num;
        sum_den = new_den;
    }

    struct SearchContext ctx = { divs, div_count, sum_num, sum_den };
    bool result = search_subset(&ctx, 0, 0, 0, 1);

    free(divs);
    return result;
}

/* ---------- Main sequence function ---------- */
seq_t a(idx_t n)
{
    static seq_t  *cache = NULL;
    static size_t cache_size = 0;
    static size_t cache_cap   = 0;
    static uint64_t last_checked = 11;   /* last integer examined */

    /* Ensure cache large enough for n terms */
    while (cache_size < (size_t)n) {
        ++last_checked;
        if (is_valid_number(last_checked)) {
            /* Grow cache */
            if (cache_cap == 0) {
                cache_cap = 16;
                cache = (seq_t*)malloc(cache_cap * sizeof(seq_t));
                if (!cache) abort();
            } else if (cache_size == cache_cap) {
                cache_cap *= 2;
                cache = (seq_t*)realloc(cache, cache_cap * sizeof(seq_t));
                if (!cache) abort();
            }
            cache[cache_size++] = (seq_t)last_checked;
        }
    }
    return cache[(size_t)n - 1];
}
